1	use crate::{ParsePkgNameError, PkgName};
2	use derive_more::{Display, Error};
3	use serde::{Deserialize, Serialize};
4	use split_first_char::SplitFirstChar;
5	use std::{borrow::Cow, str::FromStr};
6	
7	/// Syntax: `{name}@{suffix}`
8	///
9	/// Examples:
10	/// * `ts-node@10.9.1`, `@types/node@18.7.19`, `typescript@5.1.6`
11	/// * `react-json-view@1.21.3(@types/react@17.0.49)(react-dom@17.0.2)(react@17.0.2)`
12	#[derive(Debug, Display, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
13	#[display(bound(Suffix: std::fmt::Display))]
14	#[display("{name}@{suffix}")]
15	#[serde(try_from = "Cow<'de, str>", into = "String")]
16	#[serde(bound(
17	    deserialize = "Suffix: FromStr, Suffix::Err: std::fmt::Display",
18	    serialize = "Suffix: std::fmt::Display + Clone",
19	))]
20	pub struct PkgNameSuffix<Suffix> {
21	    pub name: PkgName,
22	    pub suffix: Suffix,
23	}
24	
25	impl<Suffix> PkgNameSuffix<Suffix> {
26	    /// Construct a [`PkgNameSuffix`].
27	    pub fn new(name: PkgName, suffix: Suffix) -> Self {
28	        PkgNameSuffix { name, suffix }
29	    }
30	}
31	
32	/// Error when parsing [`PkgNameSuffix`] from a string.
33	#[derive(Debug, Display, Error)]
34	#[display(bound(ParseSuffixError: Display))]
35	pub enum ParsePkgNameSuffixError<ParseSuffixError> {
36	    #[display("Input is empty")]
37	    EmptyInput,
38	    #[display("Suffix is missing")]
39	    MissingSuffix,
40	    #[display("Name is empty")]
41	    EmptyName,
42	    #[display("Failed to parse suffix: {_0}")]
43	    ParseSuffixFailure(#[error(source)] ParseSuffixError),
44	    #[display("Failed to parse name: {_0}")]
45	    ParseNameFailure(#[error(source)] ParsePkgNameError),
46	}
47	
48	impl<Suffix: FromStr> FromStr for PkgNameSuffix<Suffix> {
49	    type Err = ParsePkgNameSuffixError<Suffix::Err>;
50	    fn from_str(value: &str) -> Result<Self, Self::Err> {
51	        // The parsing code of PkgName is insufficient for this, so the code have to be duplicated for now.
52	        // TODO: use parser combinator pattern to enable code reuse
53	        let (name, suffix) = match value.split_first_char() {
54	            None => return Err(ParsePkgNameSuffixError::EmptyInput),
55	            Some(('@', rest)) => {
56	                let (name_without_at, suffix) =
57	                    rest.split_once('@').ok_or(ParsePkgNameSuffixError::MissingSuffix)?;
58	                let name = &value[..name_without_at.len() + 1];
59	                #[cfg(debug_assertions)]
60	                {
61	                    let expected = format!("@{name_without_at}");
62	                    debug_assert_eq!(name, expected);
63	                }
64	                (name, suffix)
65	            }
66	            Some((_, _)) => value.split_once('@').ok_or(ParsePkgNameSuffixError::MissingSuffix)?,
67	        };
68	        if matches!(name, "" | "@" | "@/") {
69	            return Err(ParsePkgNameSuffixError::EmptyName);
70	        }
71	        if suffix.is_empty() {
72	            return Err(ParsePkgNameSuffixError::MissingSuffix);
73	        }
74	        let suffix =
75	            suffix.parse::<Suffix>().map_err(ParsePkgNameSuffixError::ParseSuffixFailure)?;
76	        let name = name.parse().map_err(ParsePkgNameSuffixError::ParseNameFailure)?;
77	        Ok(PkgNameSuffix { name, suffix })
78	    }
79	}
80	
81	impl<'a, Suffix: FromStr> TryFrom<Cow<'a, str>> for PkgNameSuffix<Suffix> {
82	    type Error = ParsePkgNameSuffixError<Suffix::Err>;
83	    fn try_from(value: Cow<'a, str>) -> Result<Self, Self::Error> {
84	        value.parse()
85	    }
86	}
87	
88	impl<Suffix: std::fmt::Display> From<PkgNameSuffix<Suffix>> for String {
89	    fn from(value: PkgNameSuffix<Suffix>) -> Self {
90	        value.to_string()
91	    }
